// playback-demo runs an isolated, throttled local seeder and Bigflix player.
// Its synthetic video is generated by FFmpeg; no movie or public swarm is used.
package main

import (
	"bigflix/internal/catalog"
	"bigflix/internal/database"
	"bigflix/internal/downloads"
	"bigflix/internal/web"
	"context"
	"fmt"
	"github.com/anacrolix/torrent"
	"github.com/anacrolix/torrent/bencode"
	"github.com/anacrolix/torrent/metainfo"
	"golang.org/x/time/rate"
	"log"
	"net/http"
	"os"
	"os/exec"
	"os/signal"
	"path/filepath"
	"time"
)

func config() *torrent.ClientConfig {
	c := torrent.NewDefaultClientConfig()
	c.SetListenAddr("127.0.0.1:0")
	c.NoDHT = true
	c.DisableTrackers = true
	c.DisablePEX = true
	c.DisableUTP = true
	c.DisableIPv6 = true
	c.DisableWebtorrent = true
	c.DisableWebseeds = true
	c.NoDefaultPortForwarding = true
	return c
}
func main() {
	if err := run(); err != nil {
		log.Fatal(err)
	}
}
func run() error {
	root, err := os.MkdirTemp("", "bigflix-playback-demo-")
	if err != nil {
		return err
	}
	defer os.RemoveAll(root)
	source := filepath.Join(root, "source")
	os.MkdirAll(source, 0700)
	file := filepath.Join(source, "Bigflix-demo.mp4")
	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Minute)
	defer cancel()
	cmd := exec.CommandContext(ctx, "ffmpeg", "-hide_banner", "-loglevel", "error", "-f", "lavfi", "-i", "testsrc2=size=640x360:rate=24", "-f", "lavfi", "-i", "sine=frequency=440:sample_rate=44100", "-t", "180", "-c:v", "libx264", "-preset", "ultrafast", "-b:v", "800k", "-pix_fmt", "yuv420p", "-c:a", "aac", "-b:a", "64k", "-movflags", "+faststart", file)
	if out, err := cmd.CombinedOutput(); err != nil {
		return fmt.Errorf("generate video: %w: %s", err, out)
	}
	info := metainfo.Info{PieceLength: 128 << 10}
	if err = info.BuildFromFilePath(file); err != nil {
		return err
	}
	data, err := bencode.Marshal(info)
	if err != nil {
		return err
	}
	mi := &metainfo.MetaInfo{InfoBytes: data}
	cfg := config()
	cfg.DataDir = source
	cfg.Seed = true
	cfg.UploadRateLimiter = rate.NewLimiter(300<<10, 64<<10)
	seed, err := torrent.NewClient(cfg)
	if err != nil {
		return err
	}
	defer seed.Close()
	t, err := seed.AddTorrent(mi)
	if err != nil {
		return err
	}
	if err = t.VerifyData(); err != nil {
		return err
	}
	db, err := database.Open(filepath.Join(root, "data", "db.sqlite"))
	if err != nil {
		return err
	}
	defer db.Close()
	m, err := downloads.Open(db, downloads.Options{MediaDir: filepath.Join(root, "cache"), ClientConfig: config()})
	if err != nil {
		return err
	}
	defer m.Close()
	s, err := m.AddMeta(mi, "Bigflix streaming test — generated locally")
	if err != nil {
		return err
	}
	if err = m.ConnectPeer(s.Hash, seed.ListenAddrs()[0]); err != nil {
		return err
	}
	cat, err := catalog.New(db, "https://movies-api.accel.li/api/v2/", "")
	if err != nil {
		return err
	}
	handler, err := web.New(cat, m)
	if err != nil {
		return err
	}
	server := &http.Server{Addr: "127.0.0.1:3001", Handler: handler, ReadHeaderTimeout: 5 * time.Second}
	fmt.Printf("DEMO_URL=http://localhost:3001/watch/%s\n", s.Hash)
	signalCtx, stop := signal.NotifyContext(context.Background(), os.Interrupt)
	defer stop()
	done := make(chan error, 1)
	go func() { done <- server.ListenAndServe() }()
	select {
	case err := <-done:
		return err
	case <-signalCtx.Done():
		return server.Close()
	}
}
